import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listEssencesHandler } from "../handlers/listEssencesHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listEssencesHandler>>;

export function useListEssences(
  sort?: string | null,
  bookmark?: string | null,
  kind?: string | null,
  limit?: number | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listEssences", sort, bookmark, kind, limit],
    queryFn: () => listEssencesHandler(sort, bookmark, kind, limit),
    ...options,
  });
}
